const input=$json.body??$json;
const strategy=input.acquisition_strategy??{};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const decision=String(strategy.decision||input.decision||"").toLowerCase();
const mao=Number(strategy.dynamic_mao??input.dynamic_mao??input.adjusted_mao);
const asking=Number(strategy.asking_price??input.asking_price);
const projectedProfit=Number(strategy.projected_assignment_profit??input.projected_assignment_profit);
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id);
const valid=Number.isFinite(mao)&&Number.isFinite(asking)&&Number.isFinite(projectedProfit);
const eligible=["pursue","negotiate"].includes(decision)&&valid&&projectedProfit>0&&blockers.length===0;
const openingOffer=Number(input.opening_offer??input.offer_price??(Number.isFinite(asking)&&Number.isFinite(mao)?Math.min(mao,asking):NaN));
const negotiationTarget=Number(input.negotiation_target??(Number.isFinite(mao)?mao:NaN));
const offerWithinMao=Number.isFinite(openingOffer)&&Number.isFinite(mao)&&openingOffer<=mao;
const targetWithinMao=Number.isFinite(negotiationTarget)&&Number.isFinite(mao)&&negotiationTarget<=mao;
let status="offer_package_ready",nextWorkflow="WF-289",humanReview=true,reason="seller offer package prepared for human review";
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";reason="missing deal/lead/property identity";}
else if(!eligible){status="offer_package_not_ready";nextWorkflow="WF-287";reason="acquisition decision or economics are not eligible";}
else if(!offerWithinMao||!targetWithinMao){status="mao_guardrail_violation";nextWorkflow="WF-287";reason="offer or negotiation target exceeds dynamic MAO";}
const offerPackage={deal_id:input.deal_id,lead_id:input.lead_id,property_id:input.property_id,asking_price:asking,dynamic_mao:mao,opening_offer:openingOffer,negotiation_target:negotiationTarget,projected_assignment_profit:projectedProfit,motivation:strategy.motivation||input.motivation||"unknown",decision,offer_within_mao:offerWithinMao,target_within_mao:targetWithinMao,seller_review_required:true,reason};
return [{json:{...input,workflow:"WF-288",workflow_name:"Property-Level Offer Strategy → Seller Offer Package & Negotiation Launch Controller",status,offer_package:offerPackage,next_workflow:nextWorkflow,human_review_required:humanReview,audit:{event_type:"seller_offer_package_negotiation_launch",idempotency_key:input.idempotency_key||`wf-288:${input.deal_id||"unknown"}:${input.property_id||"none"}:${input.version||1}`}}}];
